import { ScrollArea as ScrollAreaPrimitive } from "@base-ui/react/scroll-area";
import { cn } from "cn";

function ScrollArea({
  className,
  children,
  ...props
}: ScrollAreaPrimitive.Root.Props) {
  return (
    <ScrollAreaPrimitive.Root
      data-slot="scroll-area"
      className={cn("relative", className)}
      {...props}
    >
      <ScrollAreaPrimitive.Viewport
        data-slot="scroll-area-viewport"
        className="size-full rounded-[inherit] outline-none transition-[color,box-shadow] focus-visible:outline-1 focus-visible:ring-[3px] focus-visible:ring-ring/50"
      >
        {children}
      </ScrollAreaPrimitive.Viewport>
      <ScrollBar />
      <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
  );
}

function ScrollBar({
  className,
  orientation = "vertical",
  ...props
}: ScrollAreaPrimitive.Scrollbar.Props) {
  return (
    <ScrollAreaPrimitive.Scrollbar
      data-slot="scroll-area-scrollbar"
      data-orientation={orientation}
      orientation={orientation}
      className={cn(
        "flex touch-none select-none p-px transition-colors data-horizontal:h-2.5 data-vertical:h-full data-vertical:w-2.5 data-horizontal:flex-col data-vertical:border-s data-vertical:border-s-transparent data-horizontal:border-t data-horizontal:border-t-transparent",
        className,
      )}
      {...props}
    >
      <ScrollAreaPrimitive.Thumb
        data-slot="scroll-area-thumb"
        className="relative flex-1 rounded-full bg-border"
      />
    </ScrollAreaPrimitive.Scrollbar>
  );
}

export { ScrollArea, ScrollBar };

[data-slot=\"input-otp-slot\"]:where([da.background:
linear-gradient(
      color-mix(in oklch, var(--background), var(--input) 55%) 0 0
    )
    padding-box,
    conic-gradient(
      from var(--otp-focus-angle),
      transparent 0% 18%,
      var(--ring) 30% 48%,
      transparent 60% 100%
    )
    border-box

[data-glass=\"true\"][data-glass-state].background-color:
color-mix(
    in srgb,
    var(--glass-base, var(--popover))
      var(--glass-opacity, var(--glass-initial-opacity, 60%)),
    transparent
  )

[data-glass=\"true\"][data-glass-state].box-shadow:
var(
      --glass-initial-edge-shadow,
      inset 0.8px 0.8px 0.4px -0.6px var(--glass-initial-edge-color),
      inset -0.8px -0.8px 0.4px -0.6px
        color-mix(in srgb, var(--glass-initial-edge-color) 70%, transparent),
      1px -1px 2px -0.5px rgb(0 0 0 / 0.1),
      -1px 1px 2px -0.5px rgb(0 0 0 / 0.07)
    ),
    var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
    var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
    var(--tw-shadow, 0 0 #0000)
